effects.preApplyScript:
if (args.targets.length !== 2) {
  ui.notifications.warn(`${this.effect.name} requiere que hagas objetivo a 2 combatientes.`);
  return false;
}

let score = 0;

for (const char of ["ws", "s", "t"]) {
  score += Math.min(1, Math.max(-1, args.targets[0].system.characteristics[char].value - args.targets[1].system.characteristics[char].value));
}

const weaker = score < 0 ? args.targets[0] : args.targets[1];
const stronger = score < 0 ? args.targets[1] : args.targets[0];

const effect = this.item.effects.get("Wy7ZKcriUh2sTLcA");
const effectData = effect.convertToApplied();
foundry.utils.setProperty(effectData.flags, "wfrp4e.targetUuid", stronger.uuid);

weaker.applyEffect({effectData});

return false;

const value = await warhammer.apps.ValueDialog.create({text: "¿De qué tamaño es la multitud afectada?"}, 0)
const crowd = Number(value);

foundry.utils.setProperty(args.effectData.flags, "wfrp4e.crowd", crowd);
args.effectData.name += ` (Tamaño de la multitud: ${crowd})`;

return true;
